fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        // Compute the boundary i + k in a signed type
        let boundary = i as i64 + k as i64;
        let mut row = Vec::with_capacity(m);
        for j in 0..m {
            if (j as i64) <= boundary {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
        }
        matrix.push(row);
    }
    matrix
}

